    return a && b ? Math.max(Math.abs(a.q - b.q), Math.abs(a.r - b.r), Math.abs((a.s === undefined ? -a.q - a.r : a.s) - (b.s === undefined ? -b.q - b.r : b.s))) : Infinity;
