    const result = [];
    for (let dq = -5; dq <= 5; dq++) for (let dr = Math.max(-5, -dq - 5); dr <= Math.min(5, -dq + 5); dr++) {
      const i = index(c.q + dq, c.r + dr); if (i >= 0) result.push(i);
    }
    return result;
  });
  const DEPOT_CELLS = Object.freeze([[10, -5], [5, 5], [-5, 10], [-10, 5], [-5, -5], [5, -10]].map(c => index(...c)));
